import { ui } from "./text";
import { useEffect, useId, useRef, useState } from "react";
import {
  pudding,
  useWidgetInteraction,
  useWidgetLocale,
  useWidgetState,
} from "@pudding/widget";
import {
  Bot,
  Check,
  ChevronDown,
  Crosshair,
  Eye,
  EyeOff,
  FileText,
  Lock,
  Mic,
  Pause,
  Play,
  RotateCcw,
  ShieldAlert,
  Sparkles,
  Unlock,
  UserRound,
  UsersRound,
  Volume2,
  VolumeX,
  X,
} from "lucide-react";
import type { Seat, WordCategory, PlayerRole } from "./types";
import {
  seatsForCount,
  isBotParticipant,
  eligibleVoteTargetsFor,
  containsOwnSecretWord,
} from "./rules";
import {
  lobby,
  position,
  start,
  speak,
  vote,
  stepBotTurn,
  pause,
  resume,
} from "./game";
import {
  t,
  setLocale,
  seatLabel,
  seatShortLabel,
  botNameForSeat,
  categoryLabel,
} from "./text";
import {
  isSoundEnabled,
  setSoundEnabled,
  playSelectSound,
  playDealSound,
  playSpeakSound,
  playVoteSound,
  playPkTieSound,
  playEliminateSound,
  playVictorySound,
} from "./sound";
import "./style.css";

type Candidates = Awaited<ReturnType<typeof pudding.interaction.candidates>>;
type SessionCandidate = Candidates["sessions"][number];

interface PlayerInfo {
  id: string;
  name: string;
  isHuman: boolean;
  isBot: boolean;
  model?: SessionCandidate["model"];
}

