import type { PlayerRole } from "./types";

let soundEnabled = true;
let audioCtx: AudioContext | null = null;
let masterBus: GainNode | null = null;
let noiseBuffer: AudioBuffer | null = null;

export function isSoundEnabled(): boolean {
  return soundEnabled;
}

export function setSoundEnabled(val: boolean): void {
  soundEnabled = val;
}

function getAudioGraph(): { ctx: AudioContext; out: AudioNode } | null {
  if (!soundEnabled || typeof window === "undefined") return null;
  try {
    if (!audioCtx) {
      const Ctx =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext: typeof AudioContext })
          .webkitAudioContext;
      if (!Ctx) return null;
      audioCtx = new Ctx();

      // Noir Studio Mastering Bus: High-Shelf Presence + Punchy Dynamics Compressor
      const presence = audioCtx.createBiquadFilter();
      presence.type = "highshelf";
      presence.frequency.value = 2200;
      presence.gain.value = 5.5;

      const comp = audioCtx.createDynamicsCompressor();
      comp.threshold.value = -14;
      comp.knee.value = 10;
      comp.ratio.value = 3.5;
      comp.attack.value = 0.002;
      comp.release.value = 0.14;

      masterBus = audioCtx.createGain();
      masterBus.gain.value = 0.92;

      masterBus.connect(presence);
      presence.connect(comp);
      comp.connect(audioCtx.destination);
    }
    if (audioCtx.state === "suspended") {
      void audioCtx.resume();
    }
    return { ctx: audioCtx, out: masterBus || audioCtx.destination };
  } catch {
    return null;
  }
}

function getWhiteNoiseBuffer(ctx: AudioContext): AudioBuffer {
  if (noiseBuffer && noiseBuffer.sampleRate === ctx.sampleRate) {
    return noiseBuffer;
  }
  const length = ctx.sampleRate * 1.5;
  const buf = ctx.createBuffer(1, length, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < length; i++) {
    data[i] = Math.random() * 2 - 1;
  }
  noiseBuffer = buf;
  return buf;
}

function playTone(
  freqStart: number,
  freqEnd: number,
  duration: number,
  type: OscillatorType = "triangle",
  gainPeak = 0.2,
  delay = 0,
) {
  const g = getAudioGraph();
  if (!g) return;
  const { ctx, out } = g;
  const now = ctx.currentTime + delay;

  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(Math.max(20, freqStart), now);
  if (freqEnd !== freqStart) {
    osc.frequency.exponentialRampToValueAtTime(
      Math.max(20, freqEnd),
      now + duration,
    );
  }

  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.linearRampToValueAtTime(gainPeak, now + 0.006);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

  osc.connect(gain);
  gain.connect(out);
  osc.start(now);
  osc.stop(now + duration + 0.02);
}

function playNoiseBurst(
  duration: number,
  filterType: BiquadFilterType,
  freqStart: number,
  freqEnd: number,
  qValue: number,
  gainPeak: number,
  delay = 0,
) {
  const g = getAudioGraph();
  if (!g) return;
  const { ctx, out } = g;
  const now = ctx.currentTime + delay;

  const src = ctx.createBufferSource();
  src.buffer = getWhiteNoiseBuffer(ctx);

  const filter = ctx.createBiquadFilter();
  filter.type = filterType;
  filter.Q.value = qValue;
  filter.frequency.setValueAtTime(Math.max(40, freqStart), now);
  if (freqEnd !== freqStart) {
    filter.frequency.exponentialRampToValueAtTime(
      Math.max(40, freqEnd),
      now + duration,
    );
  }

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.linearRampToValueAtTime(gainPeak, now + 0.004);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

  src.connect(filter);
  filter.connect(gain);
  gain.connect(out);

  src.start(now);
  src.stop(now + duration + 0.02);
}

/**
 * Crisp metallic folder/target click when selecting seats or toggling UI.
 */
export function playSelectSound(): void {
  playNoiseBurst(0.025, "bandpass", 3400, 1800, 2.2, 0.24, 0);
  playTone(1350, 2200, 0.04, "sine", 0.16, 0);
}

/**
 * Dossier deal & wax seal stamp + Noir Vibraphone Cm9 mystery chord.
 */
export function playDealSound(): void {
  // 4 rapid crisp paper dossier slides
  for (let i = 0; i < 4; i++) {
    const d = i * 0.055;
    playNoiseBurst(0.042, "bandpass", 2800 + i * 280, 1400, 1.8, 0.28, d);
    playTone(680 + i * 95, 1180 + i * 110, 0.048, "triangle", 0.14, d);
  }
  // Wax seal thump + Noir vibraphone Cm9 chord (C5, Eb5, G5, Bb5, D6)
  playTone(130, 48, 0.18, "sine", 0.35, 0.24);
  const noirNotes = [523.25, 622.25, 783.99, 932.33, 1174.66];
  noirNotes.forEach((n, idx) => {
    playTone(n, n * 1.002, 0.42, "sine", 0.13, 0.24 + idx * 0.035);
    playTone(n * 2, n * 2, 0.22, "triangle", 0.05, 0.24 + idx * 0.035);
  });
}

/**
 * Vintage mechanical typewriter burst + carriage bell ding when a testimony is submitted.
 */
export function playSpeakSound(): void {
  // 3 rapid mechanical typewriter strikes
  for (let i = 0; i < 3; i++) {
    const d = i * 0.042;
    playNoiseBurst(0.022, "highpass", 2600, 4200, 1.6, 0.28, d);
    playTone(920 + i * 140, 460, 0.03, "square", 0.1, d);
  }
  // Crisp brass desk bell ding!
  playTone(1567.98, 1567.98, 0.26, "sine", 0.22, 0.13);
  playTone(3135.96, 3135.96, 0.15, "triangle", 0.08, 0.13);
}

/**
 * Tense low heartbeat pulse + radar target lock-on double-beep when casting an accusation vote.
 */
export function playVoteSound(): void {
  // Low heartbeat lub-dub
  playTone(95, 44, 0.11, "sine", 0.38, 0);
  playTone(85, 40, 0.14, "sine", 0.32, 0.11);
  // Crisp radar reticle lock-on double-pip
  playTone(1318.5, 1318.5, 0.065, "sine", 0.22, 0.04);
  playTone(1760.0, 1760.0, 0.11, "triangle", 0.26, 0.12);
  playNoiseBurst(0.03, "bandpass", 3800, 2600, 2.5, 0.18, 0.12);
}

/**
 * Suspenseful rising dual-tone alert when a tie-break PK defense round is triggered.
 */
export function playPkTieSound(): void {
  const notes = [440, 554.37, 659.25, 880];
  notes.forEach((n, idx) => {
    playTone(n, n * 1.03, 0.14, "sawtooth", 0.15, idx * 0.065);
    playTone(n * 1.5, n * 1.5, 0.12, "triangle", 0.12, idx * 0.065);
  });
}

/**
 * Heavy iron stamp slam impact + dramatic role reveal chord when a suspect is eliminated.
 */
export function playEliminateSound(eliminatedRole: PlayerRole | null): void {
  // Stage 1: Heavy iron stamp slam (sub-bass drop + crisp paper/wood crack)
  playNoiseBurst(0.06, "highpass", 1800, 4800, 1.4, 0.55, 0);
  playNoiseBurst(0.28, "bandpass", 900, 180, 1.2, 0.48, 0.01);
  playTone(180, 34, 0.34, "sawtooth", 0.45, 0);
  playTone(110, 28, 0.38, "sine", 0.5, 0);

  // Stage 2: Role reveal stinger
  if (eliminatedRole === "Undercover") {
    // Caught an Undercover! Bright triumphant detective breakthrough chord
    const notes = [587.33, 739.99, 880, 1174.66];
    notes.forEach((n, idx) => {
      playTone(n, n, 0.36, "triangle", 0.2, 0.16 + idx * 0.045);
      playTone(n * 2, n * 2, 0.22, "sine", 0.09, 0.16 + idx * 0.045);
    });
  } else {
    // Eliminated an innocent Civilian! Tense noir minor suspense chord
    const notes = [440, 523.25, 659.25, 415.3];
    notes.forEach((n, idx) => {
      playTone(n, n * 0.99, 0.38, "sawtooth", 0.14, 0.16 + idx * 0.055);
      playTone(n, n, 0.42, "triangle", 0.18, 0.16 + idx * 0.055);
    });
  }
}

/**
 * Full cinematic finale fanfare when Civilians or Undercovers win the game.
 */
export function playVictorySound(winner: PlayerRole | null): void {
  // Stamp impact first
  playNoiseBurst(0.055, "highpass", 2000, 4500, 1.5, 0.48, 0);
  playTone(150, 38, 0.28, "sine", 0.42, 0);

  const notes =
    winner === "Civilian"
      ? [523.25, 659.25, 783.99, 1046.5, 1318.5, 1567.98] // Bright C Major 9th fanfare
      : [440, 523.25, 659.25, 830.61, 987.77, 1318.5]; // Sleek Noir Spy Master chord

  notes.forEach((n, idx) => {
    const d = 0.12 + idx * 0.075;
    const dur = idx === notes.length - 1 ? 0.65 : 0.22;
    playTone(n, n, dur, "triangle", 0.24, d);
    playTone(n * 1.5, n * 1.5, dur * 0.8, "sine", 0.1, d);
    playTone(n * 2, n * 2, dur * 0.6, "sawtooth", 0.07, d);
  });
}

files.src/style.css:
:root {
  color-scheme: dark;
  --uc-bg-deep: #0d1527;
  --uc-bg-navy: #182338;
  --uc-bg-panel: rgba(30, 41, 59, 0.9);
  --uc-gold: #f59e0b;
  --uc-gold-bright: #fbbf24;
  --uc-gold-soft: rgba(245, 158, 11, 0.32);
  --uc-crimson: #ef4444;
  --uc-crimson-bright: #f87171;
  --uc-cyan: #38bdf8;
  --uc-text-main: #f8fafc;
  --uc-text-muted: #cbd5e1;
  --uc-border-subtle: rgba(148, 163, 184, 0.26);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  background: var(--uc-bg-deep);
  color: var(--uc-text-main);
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "PingFang SC",
    "Microsoft YaHei", sans-serif;
  overflow: hidden;
  user-select: none;
}

/* Full-Bleed Responsive Noir Detective Round Table Container (Never uses 100vw so it never overflows sidebar!) */
.uc-app {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 12px 18px 16px;
  gap: 10px;
  background:
    radial-gradient(
      circle at 50% 42%,
      rgba(45, 65, 102, 0.95) 0%,
      rgba(26, 38, 62, 0.98) 58%,
      #111827 100%
    ),
    repeating-linear-gradient(
      45deg,
      rgba(255, 255, 255, 0.02) 0px,
      rgba(255, 255, 255, 0.02) 2px,
      transparent 2px,
      transparent 8px
    );
  overflow-x: hidden;
  overflow-y: auto;
}

/* Top Bar */
.uc-topbar {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 16px;
  border-radius: 13px;
  background: rgba(18, 27, 44, 0.88);
  border: 1px solid rgba(251, 191, 36, 0.35);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(12px);
  flex-wrap: wrap;
  flex-shrink: 0;
}

.uc-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.uc-emblem {
  display: flex;
  align-items: center;
  justify-content: center;
  filter: drop-shadow(0 2px 8px rgba(245, 158, 11, 0.3));
}

.uc-brand h1 {
  font-size: 16.5px;
  font-weight: 800;
  letter-spacing: 0.03em;
  background: linear-gradient(135deg, #fef08a 0%, #f59e0b 60%, #fbbf24 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.uc-status-pills {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-left: 4px;
}

.uc-phase-pill,
.uc-alive-pill,
.uc-spy-pill {
  font-size: 11.5px;
  font-weight: 600;
  padding: 2px 9px;
  border-radius: 999px;
  white-space: nowrap;
}

.uc-phase-pill {
  background: rgba(245, 158, 11, 0.16);
  border: 1px solid rgba(245, 158, 11, 0.42);
  color: #fde047;
}

.uc-alive-pill {
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.3);
  color: #7dd3fc;
}

.uc-spy-pill {
  background: rgba(220, 38, 38, 0.15);
  border: 1px solid rgba(248, 113, 113, 0.35);
  color: #fca5a5;
}

.uc-toolbar {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}

.uc-top-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 11px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.32);
  background: rgba(36, 50, 76, 0.85);
  color: #f1f5f9;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.18s ease;
}

.uc-top-btn.is-icon {
  padding: 0 8px;
}

.uc-top-btn:hover:not(:disabled) {
  border-color: rgba(245, 158, 11, 0.55);
  background: rgba(51, 65, 85, 0.85);
  color: #ffffff;
}

.uc-top-btn.is-active {
  background: rgba(245, 158, 11, 0.2);
  border-color: rgba(251, 191, 36, 0.65);
  color: #fde047;
}

.uc-top-btn.is-primary {
  background: linear-gradient(135deg, #d97706 0%, #b45309 100%);
  border-color: #fbbf24;
  color: #fffbeb;
}

.uc-top-btn.is-primary:hover:not(:disabled) {
  filter: brightness(1.1);
}

/* Error Toast */
.uc-error-toast {
  position: absolute;
  top: 64px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 10px;
  background: rgba(127, 29, 29, 0.95);
  border: 1px solid #f87171;
  color: #fef2f2;
  font-size: 13px;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.55);
}

.uc-error-toast button {
  background: transparent;
  border: none;
  color: #fecaca;
  cursor: pointer;
  display: flex;
}

/* Main Symmetrical Cross / Round-Table Arena */
.uc-arena {
  position: relative;
  z-index: 5;
  flex: 1;
  display: grid;
  grid-template-columns: minmax(196px, 236px) minmax(0, 1fr) minmax(196px, 236px);
  gap: 14px;
  align-items: center;
  min-height: 0;
}

.uc-wing {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
  height: 100%;
}

/* Agent Card (Fixed Height = Zero Vertical Jumping) */
.uc-agent-card {
  position: relative;
  width: 100%;
  height: 144px;
  min-height: 144px;
  max-height: 144px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 10px 12px;
  border-radius: 14px;
  background: linear-gradient(
    165deg,
    rgba(36, 52, 82, 0.95) 0%,
    rgba(22, 32, 54, 0.98) 100%
  );
  border: 1px solid rgba(148, 163, 184, 0.32);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  transition: transform 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease;
  overflow: hidden;
  box-sizing: border-box;
}

.uc-agent-card.is-top {
  width: 300px;
  max-width: 100%;
  height: 130px;
  min-height: 130px;
  max-height: 130px;
  flex-shrink: 0;
  padding: 8px 12px;
}

.uc-agent-card.is-turn {
  border-color: #fbbf24;
  box-shadow:
    0 0 0 2px rgba(251, 191, 36, 0.45),
    0 0 24px rgba(245, 158, 11, 0.4),
    0 12px 30px rgba(0, 0, 0, 0.45);
}

.uc-agent-card.is-pk {
  border-color: #f87171;
  box-shadow: 0 0 18px rgba(239, 68, 68, 0.32);
}

.uc-agent-card.is-votable {
  cursor: pointer;
  border-color: rgba(248, 113, 113, 0.45);
}

.uc-agent-card.is-votable:hover {
  transform: translateY(-2px);
  border-color: #ef4444;
}

.uc-agent-card.is-vote-selected {
  border-color: #ef4444;
  background: linear-gradient(
    165deg,
    rgba(69, 10, 10, 0.72) 0%,
    rgba(15, 23, 42, 0.95) 100%
  );
  box-shadow:
    0 0 0 2px rgba(239, 68, 68, 0.45),
    0 10px 28px rgba(220, 38, 38, 0.35);
}

.uc-agent-card.is-eliminated {
  opacity: 0.62;
  filter: saturate(0.45);
}

.uc-target-reticle {
  position: absolute;
  top: 9px;
  right: 9px;
  color: #f87171;
  animation: ucReticlePulse 1.1s infinite ease-in-out;
}

@keyframes ucReticlePulse {
  0%,
  100% {
    transform: scale(1) rotate(0deg);
    opacity: 0.85;
  }
  50% {
    transform: scale(1.18) rotate(45deg);
    opacity: 1;
  }
}

.uc-agent-header {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 44px;
  min-height: 44px;
  max-height: 44px;
  flex-shrink: 0;
  overflow: hidden;
}

.uc-agent-card.is-top .uc-agent-header {
  height: 42px;
  min-height: 42px;
  max-height: 42px;
}

/* Avatar with Spy Star Ring & Seat Number */
.uc-avatar-wrap {
  position: relative;
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.uc-undercover-star-ring {
  position: absolute;
  inset: -4px;
  width: 48px;
  height: 48px;
  animation: ucSlowSpin 14s linear infinite;
}

@keyframes ucSlowSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.uc-avatar-circle {
  position: relative;
  z-index: 2;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: #1e293b;
  border: 2px solid rgba(245, 158, 11, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  color: #fde047;
}

.uc-avatar-circle.is-undercover {
  border-color: #fca5a5;
}

.uc-avatar-wrap.is-turn .uc-avatar-circle {
  border-color: #fde047;
  box-shadow: 0 0 12px rgba(251, 191, 36, 0.7);
}

.uc-avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.uc-seat-num-badge {
  position: absolute;
  bottom: -3px;
  right: -4px;
  z-index: 3;
  padding: 1px 5px;
  border-radius: 6px;
  background: #182338;
  border: 1px solid rgba(251, 191, 36, 0.65);
  color: #fde047;
  font-size: 9.5px;
  font-weight: 800;
}

.uc-agent-meta {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  height: 38px;
  max-height: 38px;
  overflow: hidden;
}

.uc-agent-name-row {
  height: 18px;
  min-height: 18px;
  max-height: 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  flex-shrink: 0;
}

.uc-agent-name {
  font-size: 13px;
  font-weight: 700;
  line-height: 18px;
  color: #f8fafc;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.uc-incoming-vote-pill {
  height: 16px;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  font-size: 10.5px;
  font-weight: 700;
  padding: 0 6px;
  border-radius: 999px;
  background: rgba(220, 38, 38, 0.25);
  border: 1px solid #f87171;
  color: #fecaca;
  flex-shrink: 0;
  line-height: 1;
}

.uc-agent-tags {
  height: 18px;
  min-height: 18px;
  max-height: 18px;
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
  flex-wrap: nowrap;
  overflow: hidden;
  max-width: 100%;
  flex-shrink: 0;
}

.uc-role-badge {
  height: 18px;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  font-size: 10.5px;
  font-weight: 700;
  padding: 0 6px;
  border-radius: 5px;
  line-height: 1;
  border: 1px solid transparent;
  flex-shrink: 0;
}

.uc-role-badge::before {
  content: attr(data-label);
}

.uc-role-badge.is-civilian {
  background: rgba(56, 189, 248, 0.16);
  border: 1px solid rgba(56, 189, 248, 0.4);
  color: #7dd3fc;
}

.uc-role-badge.is-undercover {
  background: rgba(220, 38, 38, 0.22);
  border: 1px solid rgba(248, 113, 113, 0.55);
  color: #fca5a5;
}

.uc-role-badge.is-secret {
  background: rgba(148, 163, 184, 0.14);
  border: 1px solid rgba(148, 163, 184, 0.28);
  color: #cbd5e1;
}

.uc-secret-word-chip {
  height: 18px;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  font-size: 10.5px;
  font-weight: 700;
  color: #fde047;
  background: rgba(245, 158, 11, 0.14);
  border: 1px solid rgba(245, 158, 11, 0.35);
  padding: 0 6px;
  border-radius: 5px;
  line-height: 1;
  flex-shrink: 0;
}

.uc-secret-word-chip::before {
  content: attr(data-word);
}

/* Testimony & Vote Bubble Slot inside Agent Card */
.uc-agent-testimony-slot {
  height: 64px;
  min-height: 64px;
  max-height: 64px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px 8px;
  border-radius: 9px;
  background: rgba(13, 20, 36, 0.75);
  border: 1px solid rgba(148, 163, 184, 0.22);
  overflow: hidden;
  box-sizing: border-box;
}

.uc-agent-card.is-top .uc-agent-testimony-slot {
  height: 56px;
  min-height: 56px;
  max-height: 56px;
}

.uc-thinking-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  color: #fde047;
}

.uc-radar-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #fbbf24;
  box-shadow: 0 0 10px #fbbf24;
  animation: ucBlink 0.9s infinite alternate;
}

@keyframes ucBlink {
  from {
    opacity: 0.35;
    transform: scale(0.85);
  }
  to {
    opacity: 1;
    transform: scale(1.2);
  }
}

.uc-speech-bubble {
  width: 100%;
  animation: ucBubblePop 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes ucBubblePop {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.uc-speech-quote {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
  word-break: break-all;
  font-size: 12px;
  line-height: 1.4;
  max-height: 2.8em;
  color: #f1f5f9;
}

.uc-speech-bubble.is-muted .uc-speech-quote {
  color: #94a3b8;
}

.uc-speech-placeholder {
  font-size: 11.5px;
  color: rgba(203, 213, 225, 0.75);
}

.uc-vote-action-box {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.uc-vote-arrow-tag {
  align-self: flex-start;
  font-size: 11px;
  font-weight: 800;
  color: #fecaca;
  background: rgba(185, 28, 28, 0.35);
  border: 1px solid rgba(248, 113, 113, 0.5);
  padding: 1px 7px;
  border-radius: 5px;
}

.uc-vote-reason-text {
  font-size: 11px;
  color: #cbd5e1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}

/* Dramatic Eliminated Iron Stamp Slam Animation */
.uc-eliminated-stamp {
  position: absolute;
  top: 12px;
  right: 10px;
  z-index: 8;
  padding: 2px 9px;
  border: 2px solid #ef4444;
  border-radius: 6px;
  background: rgba(69, 10, 10, 0.9);
  color: #fca5a5;
  font-size: 11.5px;
  font-weight: 900;
  letter-spacing: 0.05em;
  transform: rotate(-14deg);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.5);
  animation: ucStampSlam 0.36s cubic-bezier(0.18, 0.89, 0.32, 1.28);
}

.uc-eliminated-stamp span::before {
  content: attr(data-stamp);
}

@keyframes ucStampSlam {
  0% {
    opacity: 0;
    transform: rotate(-28deg) scale(2.4);
  }
  70% {
    opacity: 1;
    transform: rotate(-12deg) scale(0.92);
  }
  100% {
    opacity: 1;
    transform: rotate(-14deg) scale(1);
  }
}

/* Center Stage: Top Seat (#3) + Classified Dossier + Bottom Centered Main Seat (#1) */
.uc-center-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  height: 100%;
  min-height: 0;
}

.uc-top-seat-holder {
  flex-shrink: 0;
  display: flex;
  justify-content: center;
  width: 100%;
}

.uc-dossier-panel {
  width: 100%;
  max-width: 580px;
  margin-left: auto;
  margin-right: auto;
  flex: 1;
  min-height: 140px;
  max-height: 340px;
  display: flex;
  flex-direction: column;
  border-radius: 16px;
  background: rgba(20, 30, 50, 0.92);
  border: 1px solid rgba(251, 191, 36, 0.36);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    0 14px 38px rgba(0, 0, 0, 0.38);
  overflow: hidden;
}

.uc-dossier-header {
  height: 38px;
  min-height: 38px;
  max-height: 38px;
  flex-shrink: 0;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 14px;
  background: rgba(36, 52, 82, 0.85);
  border-bottom: 1px solid rgba(251, 191, 36, 0.28);
  font-size: 12px;
  font-weight: 700;
  color: #fde047;
}

.uc-dossier-title-wrap {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.uc-god-word-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.uc-god-chip {
  height: 22px;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  font-size: 11px;
  font-weight: 700;
  padding: 0 8px;
  border-radius: 6px;
  white-space: nowrap;
}

.uc-god-chip::before {
  content: attr(data-pair);
}

.uc-god-chip.is-civ {
  background: rgba(56, 189, 248, 0.15);
  border: 1px solid rgba(56, 189, 248, 0.4);
  color: #7dd3fc;
}

.uc-god-chip.is-und {
  background: rgba(220, 38, 38, 0.2);
  border: 1px solid rgba(248, 113, 113, 0.45);
  color: #fca5a5;
}

.uc-dossier-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 12px 14px;
}

.uc-welcome-card {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 8px;
  padding: 10px 20px;
}

.uc-welcome-seal {
  font-size: 28px;
}

.uc-welcome-card h2 {
  font-size: 17px;
  font-weight: 800;
  color: #fde047;
}

.uc-welcome-card p {
  max-width: 420px;
  font-size: 12.5px;
  line-height: 1.5;
  color: #e2e8f0;
}

.uc-cta-btn {
  margin-top: 4px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 20px;
  border-radius: 999px;
  border: 1px solid #fde047;
  background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%);
  color: #fffbeb;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 6px 20px rgba(245, 158, 11, 0.35);
}

.uc-cta-btn:hover {
  filter: brightness(1.08);
}

/* Timeline inside Dossier */
.uc-timeline-list {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.uc-timeline-cycle {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.uc-cycle-divider {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 700;
  color: #fbbf24;
  opacity: 0.9;
}

.uc-cycle-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: rgba(245, 158, 11, 0.2);
}

.uc-log-item.is-speech {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: 12px;
  line-height: 1.42;
  padding: 4px 8px;
  border-radius: 7px;
  background: rgba(36, 52, 82, 0.65);
}

.uc-log-badge {
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 700;
  color: #93c5fd;
}

.uc-log-text {
  color: #f1f5f9;
}

.uc-log-votes-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 2px 4px;
}

.uc-mini-vote-chip {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 6px;
  background: rgba(127, 29, 29, 0.32);
  border: 1px solid rgba(248, 113, 113, 0.3);
  color: #fecaca;
}

.uc-log-elim-banner {
  padding: 5px 10px;
  border-radius: 8px;
  font-size: 11.5px;
  font-weight: 600;
}

.uc-log-elim-banner.is-undercover {
  background: rgba(20, 83, 45, 0.42);
  border: 1px solid rgba(74, 222, 128, 0.45);
  color: #bbf7d0;
}

.uc-log-elim-banner.is-civilian {
  background: rgba(127, 29, 29, 0.42);
  border: 1px solid rgba(248, 113, 113, 0.45);
  color: #fecaca;
}

.uc-victory-banner {
  margin-top: 6px;
  padding: 9px 12px;
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  animation: ucBubblePop 0.35s ease;
}

.uc-victory-banner.is-civilian-win {
  background: linear-gradient(
    135deg,
    rgba(20, 83, 45, 0.65),
    rgba(15, 23, 42, 0.9)
  );
  border: 1px solid #4ade80;
  color: #dcfce7;
}

.uc-victory-banner.is-undercover-win {
  background: linear-gradient(
    135deg,
    rgba(127, 29, 29, 0.65),
    rgba(15, 23, 42, 0.9)
  );
  border: 1px solid #f87171;
  color: #fee2e2;
}

.uc-victory-headline {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 13.5px;
}

.uc-victory-words {
  display: flex;
  gap: 16px;
  font-size: 12px;
  color: #fde047;
}

/* Bottom Centered Lead Detective Seat (#1) — Perfectly Symmetric with Top Seat (#3) */
.uc-bottom-seat-holder {
  width: 100%;
  display: flex;
  justify-content: center;
  flex-shrink: 0;
}

.uc-main-seat-card {
  position: relative;
  width: 100%;
  max-width: 560px;
  height: 136px;
  min-height: 136px;
  max-height: 136px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 6px;
  padding: 10px 16px;
  border-radius: 15px;
  background: linear-gradient(
    145deg,
    rgba(36, 52, 84, 0.95) 0%,
    rgba(22, 32, 54, 0.98) 100%
  );
  border: 1px solid rgba(251, 191, 36, 0.45);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  overflow: hidden;
  box-sizing: border-box;
}

.uc-main-seat-card.is-turn,
.uc-main-seat-card.is-my-turn {
  border-color: #fbbf24;
  box-shadow:
    0 0 0 2px rgba(251, 191, 36, 0.45),
    0 0 24px rgba(245, 158, 11, 0.45),
    0 12px 34px rgba(0, 0, 0, 0.55);
}

.uc-main-seat-card.is-eliminated {
  opacity: 0.68;
}

.uc-main-seat-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  height: 40px;
  min-height: 40px;
  max-height: 40px;
  flex-shrink: 0;
}

.uc-envelope-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.uc-envelope-agent {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.uc-envelope-agent strong {
  font-size: 13.5px;
  color: #f8fafc;
}

.uc-envelope-agent small {
  font-size: 11px;
  color: #94a3b8;
}

.uc-main-word-badge {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 5px 12px;
  border-radius: 10px;
  background: rgba(15, 23, 40, 0.82);
  border: 1px solid rgba(251, 191, 36, 0.38);
}

.uc-envelope-label-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.uc-wax-seal {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: radial-gradient(circle, #ef4444 0%, #991b1b 100%);
  border: 1px solid #fca5a5;
  color: #fff;
  font-size: 10px;
  font-weight: 900;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.uc-envelope-label {
  font-size: 11px;
  font-weight: 700;
  color: #cbd5e1;
}

.uc-mask-toggle {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border-radius: 5px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  background: rgba(15, 23, 42, 0.8);
  color: #cbd5e1;
  font-size: 10.5px;
  cursor: pointer;
}

.uc-secret-word-display {
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 0.03em;
  color: #fde047;
  text-shadow: 0 2px 8px rgba(245, 158, 11, 0.35);
}

.uc-secret-word-display::before {
  content: attr(data-word);
}

.uc-secret-word-display.is-masked {
  color: #64748b;
  text-shadow: none;
  font-size: 13.5px;
}

.uc-main-seat-body {
  height: 64px;
  min-height: 64px;
  max-height: 64px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 4px 10px;
  border-radius: 10px;
  background: rgba(14, 22, 38, 0.78);
  border: 1px solid rgba(148, 163, 184, 0.22);
  overflow: hidden;
  box-sizing: border-box;
}

.uc-main-idle-hint {
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-size: 12px;
  color: #94a3b8;
  width: 100%;
  overflow: hidden;
}

.uc-my-last-clue {
  color: #f1f5f9;
  font-weight: 500;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
  word-break: break-all;
  line-height: 1.4;
  max-height: 2.8em;
}

.uc-standby-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #cbd5e1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}

.uc-standby-status > span {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.uc-speak-input-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.uc-clue-input {
  flex: 1;
  height: 36px;
  padding: 0 12px;
  border-radius: 8px;
  border: 1px solid rgba(251, 191, 36, 0.45);
  background: rgba(16, 26, 46, 0.92);
  color: #f8fafc;
  font-size: 12.5px;
  outline: none;
}

.uc-clue-input:focus {
  border-color: #fde047;
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.2);
}

.uc-submit-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 14px;
  border-radius: 8px;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid transparent;
  flex-shrink: 0;
  white-space: nowrap;
}

.uc-submit-btn.is-gold {
  background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%);
  border-color: #fde047;
  color: #fffbeb;
}

.uc-submit-btn.is-crimson {
  background: linear-gradient(135deg, #dc2626 0%, #991b1b 100%);
  border-color: #fca5a5;
  color: #fef2f2;
}

.uc-submit-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.uc-vote-compact-wrap {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
  overflow: hidden;
}

.uc-vote-prompt {
  font-size: 11px;
  font-weight: 700;
  color: #fca5a5;
  white-space: nowrap;
  flex-shrink: 0;
}

.uc-target-pills {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  flex-shrink: 0;
  max-width: 100%;
}

.uc-target-pills::-webkit-scrollbar {
  display: none;
}

.uc-target-pill {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 7px;
  border-radius: 6px;
  border: 1px solid rgba(248, 113, 113, 0.35);
  background: rgba(69, 10, 10, 0.45);
  color: #fecaca;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
}

.uc-vote-compact-wrap .uc-speak-input-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.uc-vote-compact-wrap .uc-clue-input {
  height: 28px;
  font-size: 11.5px;
  padding: 0 8px;
}

.uc-vote-compact-wrap .uc-submit-btn {
  height: 28px;
  padding: 0 10px;
  font-size: 11.5px;
}

.uc-target-pill.is-selected {
  background: #dc2626;
  border-color: #fef08a;
  color: #ffffff;
}

.uc-waveform {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.uc-waveform span {
  width: 3px;
  height: 12px;
  border-radius: 2px;
  background: #fbbf24;
  animation: ucWave 0.8s infinite ease-in-out alternate;
}

.uc-waveform span:nth-child(2) {
  animation-delay: 0.15s;
}
.uc-waveform span:nth-child(3) {
  animation-delay: 0.3s;
}
.uc-waveform span:nth-child(4) {
  animation-delay: 0.45s;
}

@keyframes ucWave {
  from {
    transform: scaleY(0.4);
  }
  to {
    transform: scaleY(1.1);
  }
}

/* Modal & Custom Dropdowns */
.uc-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(5, 8, 17, 0.78);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.uc-modal-card {
  width: 100%;
  max-width: 640px;
  border-radius: 18px;
  background: linear-gradient(165deg, #182338 0%, #111827 100%);
  border: 1px solid rgba(251, 191, 36, 0.35);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.65);
  display: flex;
  flex-direction: column;
  max-height: 90vh;
}

.uc-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
}

.uc-modal-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.uc-modal-title-row h3 {
  font-size: 16px;
  font-weight: 800;
  color: #fde047;
}

.uc-modal-close {
  background: transparent;
  border: none;
  color: #94a3b8;
  cursor: pointer;
}

.uc-modal-body {
  padding: 16px 18px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.uc-config-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.uc-config-label {
  font-size: 12px;
  font-weight: 700;
  color: #94a3b8;
}

.uc-mode-tabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.uc-mode-tab {
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(30, 41, 59, 0.6);
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.uc-mode-tab.is-active {
  background: rgba(245, 158, 11, 0.2);
  border-color: #fbbf24;
  color: #fde047;
}

.uc-cat-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.uc-cat-pill {
  padding: 5px 12px;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(30, 41, 59, 0.6);
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.uc-cat-pill.is-active {
  background: rgba(56, 189, 248, 0.2);
  border-color: #38bdf8;
  color: #7dd3fc;
}

.uc-custom-words-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 4px;
}

.uc-custom-input {
  height: 36px;
  padding: 0 12px;
  border-radius: 8px;
  border: 1px solid rgba(251, 191, 36, 0.45);
  background: rgba(16, 26, 46, 0.92);
  color: #f8fafc;
  font-size: 12.5px;
}

.uc-seats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.uc-seat-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.uc-seat-field-label {
  font-size: 11.5px;
  font-weight: 700;
  color: #cbd5e1;
}

/* Custom Dropdown with Model Icon */
.uc-select-wrap {
  position: relative;
}

.uc-select-trigger {
  width: 100%;
  height: 48px;
  min-height: 48px;
  max-height: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 10px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.32);
  background: rgba(36, 52, 82, 0.85);
  color: #f8fafc;
  cursor: pointer;
  box-sizing: border-box;
  flex-shrink: 0;
}

.uc-select-item-left {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  flex: 1;
}

.uc-select-icon {
  width: 28px;
  height: 28px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.uc-select-icon.is-human {
  background: rgba(245, 158, 11, 0.2);
  color: #fde047;
}
.uc-select-icon.is-bot {
  background: rgba(56, 189, 248, 0.2);
  color: #7dd3fc;
}
.uc-select-icon.is-ai {
  background: rgba(168, 85, 247, 0.2);
  color: #d8b4fe;
}

.uc-select-model-img {
  width: 28px;
  height: 28px;
  border-radius: 7px;
  object-fit: cover;
  flex-shrink: 0;
}

.uc-select-texts {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.uc-select-title {
  font-size: 12.5px;
  font-weight: 700;
  line-height: 16px;
  color: #f8fafc;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}

.uc-select-sub {
  font-size: 10.5px;
  line-height: 14px;
  color: #94a3b8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}

.uc-select-chevron {
  color: #94a3b8;
  transition: transform 0.15s ease;
  flex-shrink: 0;
}

.uc-select-chevron.is-open {
  transform: rotate(180deg);
}

.uc-select-menu {
  position: fixed;
  z-index: 999;
  max-height: 240px;
  overflow-y: auto;
  border-radius: 10px;
  background: #182338;
  border: 1px solid rgba(251, 191, 36, 0.45);
  box-shadow: 0 16px 38px rgba(0, 0, 0, 0.78);
  padding: 5px;
}

.uc-select-option {
  width: 100%;
  height: 44px;
  min-height: 44px;
  max-height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 8px;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: #f8fafc;
  cursor: pointer;
  box-sizing: border-box;
  flex-shrink: 0;
}

.uc-select-option:hover,
.uc-select-option.is-selected {
  background: rgba(245, 158, 11, 0.16);
}

.uc-select-check {
  color: #fde047;
}

.uc-modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 12px 18px;
  border-top: 1px solid rgba(148, 163, 184, 0.16);
}

.uc-modal-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 16px;
  border-radius: 9px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}

.uc-modal-btn.is-ghost {
  background: transparent;
  border: 1px solid rgba(148, 163, 184, 0.3);
  color: #cbd5e1;
}

.uc-modal-btn.is-confirm {
  background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%);
  border: 1px solid #fde047;
  color: #fffbeb;
}

